#[test]
fn finds_nothing_in_nothing() {
    let empty = Written(Default::default());
    assert_eq!(uchime("empty", &[], "", None), empty);
    assert_eq!(uchime("empty-ref", &[], "", Some(REF)), empty);
}

#[test]
fn rejects_invalid_arguments() {
    for args in [
        &["--abskew", "0.5"][..],
        &["--xn", "1"],
        &["--dn", "0"],
        &["--minh", "0"],
        &["--mindiv", "0"],
        &["--mindiffs", "0"],
        &["--uchime2", "--minh", "0.5"],
        &["--width", "-1"],
    ] {
        assert_eq!(
            run("args", args, INPUT, None).0.status.code(),
            Some(2),
            "{args:?}"
        );
    }
    // de novo options do not go with a database
    for args in [&["--abskew", "2"][..], &["--uchime2"]] {
        assert_eq!(
            run("args-db", args, QUERIES, Some(REF)).0.status.code(),
            Some(2),
            "{args:?}"
        );
    }
    let (output, _) = run("bad", &[], ">a;size=0\nACGT\n", None);
    assert_eq!(output.status.code(), Some(1));
}

#[test]
fn finds_the_same_chimeras_on_any_thread_count() {
    let queries = many_queries(1500);
    for args in [
        &[][..],
        &[
            "--mindiffs",
            "1",
            "--mindiv",
            "0.3",
            "--minh",
            "0.1",
            "--width",
            "40",
        ],
        &["--xn", "6", "--dn", "1"],
    ] {
        let (output, written) = same_on_threads(
            "threads-many",
            args,
            &queries,
            Some(REF),
            &["2", "3", "5", "16", "0"],
        );
        assert!(output.status.success(), "{args:?}");
        assert_eq!(written.0[3].lines().count(), 1500, "{args:?}");
    }
    // de novo the input is the database. It runs on one thread whatever -t
    let (output, _) = same_on_threads("threads-many-denovo", &[], &many_queries(300), None, &["4"]);
    assert!(output.status.success());
}

#[test]
fn stops_at_an_invalid_query_as_on_one_thread() {
    let queries = many_queries(1200);
    for bad in [">bad;size=0\nACGT\n", ">bad\nAC\u{1}GT\n"] {
        for input in [
            format!("{queries}{bad}{queries}"),
            format!("{bad}{queries}"),
        ] {
            let (output, _) =
                same_on_threads("threads-invalid", &[], &input, Some(REF), &["2", "3", "8"]);
            assert_eq!(output.status.code(), Some(1));
        }
    }
}

#[test]
fn takes_the_thread_count() {
    let expected = uchime("threads-t", &[], QUERIES, Some(REF));
    for t in [&["-t", "0"][..], &["--threads", "5"], &["-t", "1025"]] {
        let (output, written) = run("threads-t", t, QUERIES, Some(REF));
        assert!(output.status.success(), "{t:?}");
        assert_eq!(written, expected, "{t:?}");
    }
    for t in ["-1", "x", "1.5", ""] {
        assert_eq!(
            run("threads-t", &["-t", t], QUERIES, Some(REF))
                .0
                .status
                .code(),
            Some(2),
            "{t:?}"
        );
    }
}

/// Runs uchime with `args` on `input`, writing every output, the
/// database `db` given.
fn run(name: &str, args: &[&str], input: &str, db: Option<&str>) -> (Output, Written) {
    run_at(None, name, args, input, db)
}

/// The SIMD levels of this processor, scalar with SSE2 and AVX2 or with
/// NEON. Each aligns eight or sixteen targets at once and must give the
/// output of the others.
fn levels() -> Vec<rsearch::simd::Level> {
    let levels = rsearch::simd::available();
    #[cfg(any(target_arch = "x86_64", target_arch = "aarch64"))]
    assert!(levels.len() >= 2, "{levels:?}");
    levels
}

#[test]
fn finds_the_same_chimeras_at_every_simd_level() {
    let levels = levels();
    let queries = many_queries(800);
    for (args, db) in [
        (&[][..], Some(REF)),
        (
            &["--mindiffs", "1", "--mindiv", "0.3", "--minh", "0.1"][..],
            Some(REF),
        ),
        (&[][..], None),
    ] {
        let input = if db.is_some() {
            queries.clone()
        } else {
            many_queries(300)
        };
        let runs: Vec<(Output, Written)> = levels
            .iter()
            .map(|&level| run_at(Some(level), "levels", args, &input, db))
            .collect();
        assert!(runs[0].0.status.success(), "{args:?}");
        for (level, (output, written)) in levels.iter().zip(&runs).skip(1) {
            assert!(output.status.success(), "{level:?} {args:?}");
            assert!(
                written.0 == runs[0].1.0,
                "{level:?} writes otherwise, {args:?}"
            );
        }
    }
}
